// Run with a modern Node runtime. Fixtures were generated by Python Astronomy Engine.
var fs=require('fs'),vm=require('vm'),assert=require('assert');
var context={document:{body:{dataset:{skyLabels:'false'},classList:{contains:()=>false}}}};vm.createContext(context);
for(var name of ['vendor/astronomy.browser.min.js','star-catalog.js','celestial-sky.js'])vm.runInContext(fs.readFileSync('static/'+name,'utf8'),context);
vm.runInContext('this.sky=CelestialSky;this.catalog=StarCatalog;',context);
var cases=JSON.parse(fs.readFileSync('tests/celestial-fixtures.json','utf8'));
assert.equal(context.catalog.length,5070);
for(var c of cases){
 var points=context.sky.snapshot(Date.parse(c.time),c.lat,c.lon,c.height);
 for(var expected of c.points){
  var actual=points.find(p=>p.name===expected.name);
  if(expected.alt< -1&&!actual)continue;
  assert.ok(actual,expected.name+' missing');
  var error=Math.max(Math.abs(((actual.az-expected.az+540)%360)-180)*Math.cos(expected.alt*Math.PI/180),Math.abs(actual.alt-expected.alt));
  assert.ok(error<.002,expected.name+' horizontal error '+error);
  if('mag'in expected)assert.ok(Math.abs(actual.mag-expected.mag)<.00001);
 }
}
var at=context.sky.snapshot(Date.parse(cases[0].time),cases[0].lat,cases[0].lon,cases[0].height);
var later=context.sky.snapshot(Date.parse(cases[0].time)+3600000,cases[0].lat,cases[0].lon,cases[0].height);
var vega=at.find(p=>p.name==='Vega'),vegaLater=later.find(p=>p.name==='Vega');
assert.ok(Math.abs(vega.az-vegaLater.az)>1);
assert.equal(context.sky.aboveTerrain({az:359.9,alt:4},[5,5,5,5]),false);
assert.equal(context.sky.aboveTerrain({az:0,alt:6},[5,5,5,5]),true);
assert.ok(context.sky.limitingMagnitude(-18)>context.sky.limitingMagnitude(-6));
console.log('PASS: 5,070 real stars; planet/star coordinates match independent Python fixtures; time motion, terrain occlusion and twilight visibility.');
